int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    // (neighbor, 1 if the original edge points away from this node)
    vector<vector<pair<int, int>>> graph(n);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        graph[a].push_back({b, 1});
        graph[b].push_back({a, 0});
    }
    vector<pair<int, int>> stack = {{0, -1}};
    long long answer = 0;
    while (!stack.empty()) {
        auto [v, parent] = stack.back();
        stack.pop_back();
        for (auto [w, cost] : graph[v])
            if (w != parent) {
                answer += cost;  // parent -> child edge must be reversed
                stack.push_back({w, v});
            }
    }
    cout << answer << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        // adjacency list in arrays: edge e goes to to[e]; cost[e] = 1 if it points away from its owner
        int[] head = new int[n], next = new int[2 * n], to = new int[2 * n], cost = new int[2 * n];
        Arrays.fill(head, -1);
        int edges = 0;
        for (int i = 0; i < n - 1; i++) {
            int a = nextInt(), b = nextInt();
            to[edges] = b; cost[edges] = 1; next[edges] = head[a]; head[a] = edges++;
            to[edges] = a; cost[edges] = 0; next[edges] = head[b]; head[b] = edges++;
        }
        int[] stack = new int[n], parentOf = new int[n];
        int top = 0;
        stack[top++] = 0;
        parentOf[0] = -1;
        long answer = 0;
        while (top > 0) {
            int v = stack[--top];
            for (int e = head[v]; e != -1; e = next[e]) {
                int w = to[e];
                if (w != parentOf[v]) {
                    answer += cost[e]; // parent -> child edge must be reversed
                    parentOf[w] = v;
                    stack[top++] = w;
                }
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

type edge struct{ to, cost int }

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	// cost 1 if the original edge points away from this node
	graph := make([][]edge, n)
	for i := 0; i < n-1; i++ {
		a, b := int(nextInt()), int(nextInt())
		graph[a] = append(graph[a], edge{b, 1})
		graph[b] = append(graph[b], edge{a, 0})
	}
	type frame struct{ v, parent int }
	stack := []frame{{0, -1}}
	answer := 0
	for len(stack) > 0 {
		f := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		for _, e := range graph[f.v] {
			if e.to != f.parent {
				answer += e.cost // parent -> child edge must be reversed
				stack = append(stack, frame{e.to, f.v})
			}
		}
	}
	fmt.Println(answer)
}
